import json
nb = json.load(open("repo/robust_estim_sbm.ipynb", encoding="utf-8"))
out = []
for i in range(48, 70):
    c = nb["cells"][i]
    if c["cell_type"] != "code":
        continue
    outs = c.get("outputs", [])
    if not outs:
        continue
    out.append(f"===== [{i}] outputs =====")
    for o in outs:
        t = o.get("output_type")
        if t == "stream":
            out.append("".join(o.get("text", [])))
        elif t == "execute_result":
            data = o.get("data", {})
            if "text/plain" in data:
                out.append("".join(data["text/plain"]))
            elif "image/png" in data:
                out.append("<image/png omitted>")
        elif t == "error":
            out.append(f"ERROR: {o.get('ename')}: {''.join(o.get('evalue',''))}")
        else:
            out.append(f"<{t}>")
    out.append("")
open("cells_outputs.txt", "w", encoding="utf-8").write("\n".join(out))
print("wrote", len(out), "lines")

